<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ApiError, rowsOf, type Api, type Row } from '../lib/api'
import { useAccess } from '../lib/access'
import { display, labels } from '../lib/presentation'
import DataTable from './DataTable.vue'
const props = defineProps<{api: Api}>()
const can = useAccess()
const kinds = [
 { id: 'shifts', title: 'الورديات', write: 'catalogs.manage', approve: '', fields: ['code','name_ar','start_time','end_time','effective_from','effective_until'] },
 { id: 'operational-calendar', title: 'تقويم العمل', write: 'catalogs.manage', approve: '', fields: ['shift_code','business_date','starts_at','ends_at','source_reference'] },
 { id: 'unit-status-intervals', title: 'حالات الوحدات', write: 'production.write', approve: 'production.approve', fields: ['unit_id','state','started_at','ended_at','known_at','derating_factor','source_reference'] },
 { id: 'quality-specifications', title: 'مواصفات الجودة', write: 'quality.write', approve: 'quality.approve', fields: ['product_id','parameter_code','name_ar','unit_code','spec_min','spec_max','effective_from','effective_until','source_reference'] },
] as const
const names: Record<string,string> = { code:'رمز الوردية',name_ar:'الاسم',start_time:'بداية الوردية بالتوقيت المحلي',end_time:'نهاية الوردية بالتوقيت المحلي',effective_from:'ساري من',effective_until:'ساري حتى',shift_code:'رمز الوردية',business_date:'يوم العمل',starts_at:'البداية UTC',ends_at:'النهاية UTC',source_reference:'مرجع المصدر',unit_id:'الوحدة',state:'حالة الوحدة',started_at:'البداية UTC',ended_at:'النهاية UTC، اختياري',known_at:'وقت معرفة الحالة UTC، اختياري',derating_factor:'معامل التخفيض، مطلوب عند التخفيض',product_id:'المنتج، اختياري',parameter_code:'رمز الخاصية',unit_code:'وحدة القياس',spec_min:'الحد الأدنى، اختياري',spec_max:'الحد الأعلى، اختياري' }
const dates = ['effective_from','effective_until','business_date'], times = ['start_time','end_time'], instants = ['starts_at','ends_at','started_at','ended_at','known_at'], optional = ['effective_until','ended_at','known_at','derating_factor','product_id','spec_min','spec_max']
const current = ref(0), kind = computed(() => kinds[current.value]!), facility = ref(''), units = ref<Row[]>([]), facilities = ref<Row[]>([]), products = ref<Row[]>([]), measureUnits = ref<Row[]>([]), rows = ref<Row[]>([]), selected = ref<Row | null>(null)
const form = reactive<Record<string,string>>({}), reason = ref(''), error = ref(''), success = ref(''), loading = ref(false), busy = ref(false)
const checkSample = ref(''), conformance = ref<Row | null>(null), downtimeUnit = ref(''), from = ref(''), asOf = ref(''), downtime = ref<Row | null>(null)
const cols = computed(() => ({ shifts:['code','name_ar','start_time','end_time','effective_from'], 'operational-calendar':['business_date','shift_id','starts_at','ends_at','source_reference'], 'unit-status-intervals':['unit_id','state','started_at','ended_at','status'], 'quality-specifications':['parameter_code','name_ar','unit_code','spec_min','spec_max','version','status'] })[kind.value.id])
function message(e: unknown) { error.value = e instanceof ApiError ? e.message : 'تعذر تنفيذ الطلب.' }
async function load() { rows.value=[]; selected.value=null; if (!facility.value) return; loading.value=true; error.value=''; try { rows.value=rowsOf(await props.api(`/references/${kind.value.id}?${new URLSearchParams({facility_id:facility.value})}`)) } catch(e) { message(e) } finally { loading.value=false } }
watch([current,facility], () => { Object.keys(form).forEach(key => delete form[key]); success.value=''; void load() })
onMounted(async () => { for (const [path,target] of [['facilities',facilities],['units',units],['products',products],['measurement-units',measureUnits]] as const) { try { target.value=rowsOf(await props.api(`/catalogs/${path}`)) } catch { /* Scope may deny a catalog. */ } } })
function utc(value: string) { return value ? `${value}:00Z` : null }
async function save() { busy.value=true; error.value=''; success.value=''; const body: Row={facility_id:facility.value}; for (const field of kind.value.fields) { const value=form[field] ?? ''; body[field]=instants.includes(field) ? utc(value) : value === '' ? null : value } try { await props.api(`/references/${kind.value.id}`,{method:'POST',body}); success.value = kind.value.approve ? 'حُفظ السجل بانتظار مراجعة مستقلة.' : 'حُفظ السجل وأثره التدقيقي.'; await load() } catch(e) { message(e) } finally { busy.value=false } }
async function approve() { if (!selected.value || reason.value.trim().length<10) { error.value='أدخل سببًا للمراجعة من عشرة أحرف على الأقل.'; return } busy.value=true; error.value=''; try { await props.api(`/references/${kind.value.id}/${selected.value.id}/approve`,{method:'POST',body:{reason:reason.value}}); success.value='تم الاعتماد المستقل وتوثيق القرار.'; reason.value=''; await load() } catch(e) { message(e) } finally {busy.value=false} }
async function checkQuality() { error.value=''; conformance.value=null; try { conformance.value=(await props.api<{data:Row}>(`/quality-samples/${encodeURIComponent(checkSample.value)}/conformance`)).data } catch(e) {message(e)} }
async function checkDowntime() { error.value=''; downtime.value=null; try { const query=new URLSearchParams({unit_id:downtimeUnit.value,from:utc(from.value) ?? '',as_of:utc(asOf.value) ?? ''}); downtime.value=(await props.api<{data:Row}>(`/unit-status/downtime?${query}`)).data } catch(e) {message(e)} }
</script>
<template><section>
 <div class="panel"><div class="panel-title"><h2>المرفق والمرجع</h2></div><label>المرفق<select v-model="facility" aria-label="المرفق" required><option value="">اختر المرفق</option><option v-for="f in facilities" :key="String(f.id)" :value="String(f.id)">{{ f.name_ar }}</option></select></label><div class="button-row"><button v-for="(item,index) in kinds" :key="item.id" class="button secondary" :aria-pressed="current===index" @click="current=index">{{ item.title }}</button></div></div>
 <p v-if="error" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice positive" role="status">{{ success }}</p>
 <div v-if="can(kind.write) && facility" class="panel"><div class="panel-title"><h2>إضافة {{ kind.title }}</h2></div><form data-test="reference-form" @submit.prevent="save"><div class="form-grid"><label v-for="field in kind.fields" :key="field">{{ names[field] }}
 <select v-if="field==='unit_id' || field==='product_id' || field==='unit_code'" v-model="form[field]" :name="field" :required="!optional.includes(field)"><option value="">اختر</option><option v-for="item in (field==='unit_id' ? units.filter(u => u.facility_id===facility) : field==='product_id' ? products : measureUnits)" :key="String(item.id ?? item.code)" :value="String(field==='unit_code' ? item.code : item.id)">{{ item.name_ar ?? item.display_symbol ?? item.code }}</option></select>
 <select v-else-if="field==='state'" v-model="form[field]" :name="field" required><option value="">اختر</option><option value="running">تشغيل</option><option value="trip">توقف مفاجئ</option><option value="startup">بدء تشغيل</option><option value="maintenance">صيانة</option><option value="derated">تخفيض</option><option value="shutdown">توقف</option></select>
 <input v-else v-model="form[field]" :name="field" :type="dates.includes(field) ? 'date' : times.includes(field) ? 'time' : instants.includes(field) ? 'datetime-local' : 'text'" :inputmode="['spec_min','spec_max','derating_factor'].includes(field) ? 'decimal' : undefined" :required="!optional.includes(field)" />
 </label></div><p class="muted">التواريخ المسجلة بـ UTC تُدخل حسب التوقيت العالمي؛ حدود الجودة تظل معلّقة حتى الاعتماد.</p><button class="button primary" :disabled="busy">حفظ السجل</button></form></div>
 <div class="panel"><div class="panel-title"><h2>{{ kind.title }}</h2><button class="text-button" @click="load">تحديث</button></div><p v-if="loading" role="status">جارٍ التحميل…</p><div v-else-if="!rows.length" class="empty-state"><h3>لا توجد سجلات</h3><p>اختر مرفقًا لعرض البيانات المتاحة حسب صلاحيتك.</p></div><DataTable v-else :rows="rows" :columns="cols" selectable @select="selected=$event" /></div>
 <div v-if="selected" class="panel"><h2>تفاصيل ومراجعة السجل</h2><dl class="detail-grid"><div v-for="(value,key) in selected" :key="key"><dt>{{ names[String(key)] ?? labels[String(key)] ?? key }}</dt><dd>{{ display(value) }}</dd></div></dl><form v-if="selected.status==='pending' && kind.approve && can(kind.approve)" @submit.prevent="approve"><label>سبب الاعتماد المستقل<textarea v-model="reason" minlength="10" required /></label><button class="button primary" :disabled="busy">اعتماد</button></form></div>
 <div v-if="can('quality.read')" class="panel"><h2>مطابقة عينة جودة مع المواصفة المعتمدة</h2><form @submit.prevent="checkQuality"><label>معرّف العينة<input v-model="checkSample" required /></label><button class="button secondary">فحص المطابقة</button></form><p v-if="conformance" role="status">{{ conformance.status === 'conforming' ? 'مطابقة' : conformance.status === 'out_of_spec' ? 'خارج المواصفة' : 'لم يُقيّم: عينة أو مواصفة معتمدة مطابقة غير متوفرة' }} · {{ display(conformance.reason) }}</p></div>
 <div v-if="can('engineering.read')" class="panel"><h2>مدة توقف الوحدة</h2><form @submit.prevent="checkDowntime"><div class="form-grid"><label>الوحدة<select v-model="downtimeUnit" required><option value="">اختر</option><option v-for="u in units.filter(u => u.facility_id===facility)" :key="String(u.id)" :value="String(u.id)">{{ u.name_ar }}</option></select></label><label>من UTC<input v-model="from" type="datetime-local" required /></label><label>حتى UTC<input v-model="asOf" type="datetime-local" required /></label></div><button class="button secondary">حساب المدة المعتمدة</button></form><p v-if="downtime" role="status">{{ display(downtime.seconds) }} ثانية من الفترات المعتمدة دون تكرار التداخل. التخفيض الجزئي منفصل.</p></div>
</section></template>
